jQuery dominated 2008-2018. Modern browsers shrank its job — but you'll still see it in legacy code, WordPress themes, and many enterprise apps.
<script src="https://code.jquery.com/jquery-3.7.1.min.js"></script>
// selector + chaining
$('#btn')
.text('Go!')
.addClass('primary')
.on('click', (e) => {
e.preventDefault();
$('#result').fadeIn(200).text('clicked');
});
// AJAX
$.getJSON('/api/users', users => {
users.forEach(u => $('<li>').text(u.name).appendTo('#users'));
});
Vanilla-JS equivalents:
jQuery · Modern JS
$('.x') · document.querySelectorAll('.x')
$.ajax / $.get / $.post · fetch(url, options)
$(el).addClass('y') · el.classList.add('y')
$(el).on('click', fn) · el.addEventListener('click', fn)
$(el).fadeIn() · CSS transitions on opacity
Trick: for new projects, skip jQuery. The vanilla DOM API is good enough since ~2017. For legacy projects, keep jQuery — re-platforming costs more than the bytes.

Static HTML; on form submit, append a new <li> with the entered text + a delete button. Persist to localStorage across reloads.
Skeleton
const form = document.querySelector('#new');
const list = document.querySelector('#list');
const save = (items) => localStorage.setItem('todos', JSON.stringify(items));
const load = () => JSON.parse(localStorage.getItem('todos') || '[]');
const render = () => {
list.innerHTML = '';
for (const [i, text] of load().entries()) {
const li = document.createElement('li');
li.textContent = text;
const x = document.createElement('button');
x.textContent = '×';
x.addEventListener('click', () => {
const items = load(); items.splice(i, 1); save(items); render();
});
li.append(x);
list.append(li);
}
};
form.addEventListener('submit', (e) => {
e.preventDefault();
const v = form.elements.text.value.trim();
if (!v) return;
const items = load(); items.push(v); save(items);
form.reset(); render();
});
render();
